import duckdb,boto3,json
cr=boto3.Session(profile_name='scrapivo').get_credentials().get_frozen_credentials(); c=duckdb.connect(); c.execute('LOAD httpfs'); c.execute("SET s3_region='us-east-2'"); c.execute("SET s3_access_key_id=?",[cr.access_key]); c.execute("SET s3_secret_access_key=?",[cr.secret_key]);
if cr.token:c.execute("SET s3_session_token=?",[cr.token])
c.execute("create view d as select * from read_parquet('s3://scrapivo-raw-data-2026-523220341033-us-east-2-an/processed/companies_by_initial/*/*.parquet',union_by_name=true,hive_partitioning=true)")
q="""select count(*) total,count(distinct location) locations,count(distinct category) categories,sum((website is not null and trim(website)<>'')::int) website,sum((email is not null and trim(email)<>'')::int) email,sum((phone is not null and trim(phone)<>'')::int) phone,sum((linkedin is not null and trim(linkedin)<>'')::int) linkedin,sum(((facebook is not null and trim(facebook)<>'') or (twitter is not null and trim(twitter)<>''))::int) other_social,sum(((website is not null and trim(website)<>'') or (email is not null and trim(email)<>'') or (phone is not null and trim(phone)<>'') or (linkedin is not null and trim(linkedin)<>'') or (facebook is not null and trim(facebook)<>'') or (twitter is not null and trim(twitter)<>''))::int) any_contact,sum((description is not null and trim(description)<>'')::int) description,sum((funding_total is not null and trim(funding_total)<>'')::int) funding,count(*)-count(distinct case when external_id is not null and trim(external_id)<>'' then external_id end)-sum((external_id is null or trim(external_id)='')::int) duplicate_external,count(case when website is not null and trim(website)<>'' then 1 end)-count(distinct case when website is not null and trim(website)<>'' then website end) duplicate_website_extra from d"""
r=c.execute(q); out=dict(zip([x[0] for x in r.description],r.fetchone())); out['top_locations']=c.execute("select location,count(*) n from d group by location order by n desc limit 30").fetchall(); out['top_categories']=c.execute("select category,count(*) n from d group by category order by n desc limit 30").fetchall();
open('reports/gate2/_company-profile.json','w').write(json.dumps(out,indent=2,default=str)); print('done')